router = APIRouter(
    prefix="/admin",
    tags=["Admin"],
)


class CategoryUpdate(BaseModel):
    category_name: str = Field(
        ...,
        min_length=1,
        max_length=100,
    )

    @field_validator("category_name")
    @classmethod
    def validate_category_name(cls, value: str) -> str:
        cleaned_value = value.strip()

        if not cleaned_value:
            raise ValueError(
                "Category name cannot be empty"
            )

        return cleaned_value


def convert_value_error(error: ValueError) -> HTTPException:
    message = str(error)
    message_lower = message.lower()

    if "not found" in message_lower:
        error_status = status.HTTP_404_NOT_FOUND
    elif "already exists" in message_lower:
        error_status = status.HTTP_409_CONFLICT
    else:
        error_status = status.HTTP_400_BAD_REQUEST

    return HTTPException(
        status_code=error_status,
        detail=message,
    )


@router.post(
    "/products",
    response_model=ProductResponse,
    status_code=status.HTTP_201_CREATED,
    dependencies=[Depends(require_roles("admin"))],
)
def create_admin_product(
    product_data: ProductCreate,
    db: Session = Depends(get_db),
):
    try:
        return product_service.create_product(
            db=db,
            product_data=product_data,
        )
    except ValueError as error:
        raise convert_value_error(error) from error
    except IntegrityError as error:
        db.rollback()
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="Product name already exists",
        ) from error


