@router.put(
    "/products/{product_id}",
    response_model=ProductResponse,
    dependencies=[Depends(require_roles("admin"))],
)
def update_admin_product(
    product_data: ProductUpdate,
    product_id: int = Path(..., gt=0),
    db: Session = Depends(get_db),
):
    product = product_repository.get_product_by_id(
        db=db,
        product_id=product_id,
    )

    if product is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Product not found",
        )

    updates = product_data.model_dump(
        exclude_unset=True,
    )

    if "category_id" in updates:
        category = category_repository.get_category_by_id(
            db=db,
            category_id=updates["category_id"],
        )

        if category is None:
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND,
                detail="Category not found",
            )

    if "product_name" in updates:
        duplicate_product = (
            db.query(Product)
            .filter(
                Product.ProductName == updates["product_name"],
                Product.ProductID != product_id,
            )
            .first()
        )

        if duplicate_product is not None:
            raise HTTPException(
                status_code=status.HTTP_409_CONFLICT,
                detail="Product name already exists",
            )

    field_mapping = {
        "product_name": "ProductName",
        "description": "Description",
        "category_id": "CategoryID",
        "price": "Price",
        "available_quantity": "AvailableQuantity",
        "product_url": "ProductUrl",
    }

    for schema_field, model_field in field_mapping.items():
        if schema_field not in updates:
            continue

        value = updates[schema_field]

        if schema_field == "product_url" and value is not None:
            value = str(value)

        setattr(product, model_field, value)

    try:
        db.commit()
        db.refresh(product)
        return product
    except IntegrityError as error:
        db.rollback()
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="Product update violates a database constraint",
        ) from error


