@router.put(
    "/categories/{category_id}",
    response_model=CategoryResponse,
    dependencies=[Depends(require_roles("admin"))],
)
def update_admin_category(
    category_data: CategoryUpdate,
    category_id: int = Path(..., gt=0),
    db: Session = Depends(get_db),
):
    category = category_repository.get_category_by_id(
        db=db,
        category_id=category_id,
    )

    if category is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Category not found",
        )

    duplicate_category = (
        db.query(Category)
        .filter(
            Category.CategoryName == category_data.category_name,
            Category.CategoryID != category_id,
        )
        .first()
    )

    if duplicate_category is not None:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="Category already exists",
        )

    category.CategoryName = category_data.category_name

    try:
        db.commit()
        db.refresh(category)
        return category
    except IntegrityError as error:
        db.rollback()
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="Category update violates a database constraint",
        ) from error


